"""Find integration error if Simpson method is used.

    Args:
        max_forth_derivative: precalculated value.
        low: left range boundary.
        high: right range boundary.
        length: number of values in range.
    Returns:
        float: approximate integration error.

    """
def calculate_integration_error(
    max_forth_derivative: float, low: float, high: float, length: int
) -> float {
    step = (high - low) / length;
    return (((step ** 4) / 180) * max_forth_derivative * (high - low));
}

""" calculates mean of generator or iterator.
    Returns `empty` in case of an empty sequence """
def mean(values: Any, empty: Any = 0) -> object {
    (n, mean) = (0, 0);
    for value in values {
        n += 1;
        mean += (value - mean) / n;
    }
    return mean if (n > 0) else empty;
}

"""Find utm zone for lon and lat values.

    lon -180 -- -174 -> 1 ... 174 -- 180 -> 60
    lat < 0 hemisphere = S, > 0 hemisphere = N

    Parameters
    ----------
    lon : float
    lat : float

    Returns
    -------
    str :
        zone + hemisphere
    """
def findUTMZone(lon: Any, lat: Any) -> object {
    zone = int(((int(lon) + 180) / 6)) + 1;
    if (lat > 0) {
        return (str(zone) + 'N');
    }
    return (str(zone) + 'S');
}

"""
    sets_compare_label
    input: [data [tuple list [ tuple ...] ... ] ...]
    output: num_correct, num_pred, num_label
    NOTE: basic set should be tuple
    """
def sets_compare(sets_predict: Any, sets_label: Any) -> object {
    num_correct = 0;
    num_pred = 0;
    num_label = 0;
    for (set_1, set_2) in zip(sets_predict, sets_label) {
        set_1 = `set(set_1);
        set_2 = `set(set_2);
        num_pred += len(set_1);
        num_label += len(set_2);
        num_correct += len((set_1 & set_2));
    }
    return (num_correct, num_pred, num_label);
}

