"""Determines the type of val, returning a "full path" string.

  For example:
    DetermineType(5) -> __builtin__.int
    DetermineType(Foo()) -> com.google.bar.Foo

  Args:
    value: Any value, the value is irrelevant as only the type metadata
    is checked

  Returns:
    Type path string.  None if type cannot be determined.
  """
def DetermineType(value: Any) -> object {
    object_type = `type(value);
    if not hasattr(object_type, '__name__') {
        return None;
    }
    type_string = getattr(object_type, '__module__', '');
    if type_string {
        type_string += '.';
    }
    type_string += object_type.__name__;
    return type_string;
}

"""
    Get a tuple of the first entries found in an psimitab column
    (xref, value, desc)
    :param field_string:
    :return: A tuple (xref, value, desc) - desc is optional
    """
def parse_field(field_string: Any) -> object {
    parts = field_string.split(":");
    xref = parts[0];
    rest = parts[1];
    if ("(" in rest) {
        subfields = rest.split("(");
        value = subfields[0];
        desc = subfields[1][:-1];
    } else {
        value = rest;
        desc = "NA";
    }
    return (xref, value, desc);
}
